import {installVanityExplorer} from './vanity-explorer.js';
import {vanityStyles as styles,vanityFamilies as families,vanityProducts as products,vanityExtras as extras,bathroomPresets as presets} from './vanity-data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;'),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const explorer=installVanityExplorer({products,styles});
const key='kabbie-bathroom-plan-six-finishes-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}
const state={style:styles.some(s=>s.id===saved.style)?saved.style:'colorado-white',items:Array.isArray(saved.items)?saved.items.filter(x=>typeof x==='string'&&[...products,...extras].some(p=>p.id===x)).slice(0,12):[],view:'plan',room:saved.room&&typeof saved.room==='object'?saved.room:{}};
const fields={'v-room-width':[36,240,84],'v-room-depth':[48,240,96],'v-run-offset':[0,240,6],'v-run-gap':[0,12,1],'v-drain-x':[0,240,21],'v-drain-height':[0,60,18],'v-basin-width':[8,36,18],'v-basin-depth':[8,24,13]};
for(const [id,[min,max,fallback]]of Object.entries(fields))$('#'+id).value=Number.isFinite(Number(state.room[id]))?Math.max(min,Math.min(max,Number(state.room[id]))):fallback;
for(const [id,allowed]of Object.entries({'v-plumbing-exit':['wall','floor'],'v-basin-type':['undermount','dropin','vessel']}))if(allowed.includes(state.room[id]))$('#'+id).value=state.room[id];
function save(){state.room=Object.fromEntries([...Object.keys(fields),'v-plumbing-exit','v-basin-type'].map(id=>[id,$('#'+id).value]));try{localStorage.setItem(key,JSON.stringify({style:state.style,items:state.items,room:state.room}));}catch{}}
function feedback(s){$('#v-feedback').textContent=s;}
function current(){return styles.find(s=>s.id===state.style);}
function price(p){return p.sale?Math.round(p.price*.85*100)/100:p.price;}
function unit(id){const p=products.find(p=>p.id===id)||extras.find(p=>p.id===id),s=styles.find(s=>s.id===p.style);return {...p,color:s?.color||p.color,styleData:s};}
function chooseStyle(id,scroll=false,allColors=false){if(scroll)$('#v-cabinets').hidden=false;state.style=id;const s=current(),family=families.find(f=>f.id===s.family),finishes=styles.filter(x=>x.family===s.family);$$('[data-v-style]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.vStyle===id)));$$('[data-v-family-card]').forEach(b=>b.classList.toggle('selected',b.dataset.vFamilyCard===s.family));$('#v-selected-title').textContent=family.name+' · sizes & colors';$('#v-selected-image').src='/kabbie/assets/vanities/'+s.image;$('#v-selected-image').alt=s.name+' vanity styling concept';$('#v-selected-description').innerHTML=`<span class="eyebrow">${s.profile} · ${s.mount}</span><h3>${s.name}</h3><p>${s.copy}</p><span class="v-finish"><i style="background:${s.color}"></i>${s.finish}</span><p>${s.surface}<br><small>${s.construction}</small></p>`;$('#v-color-filter').innerHTML='<option value="all">All colors in this style</option>'+finishes.map(x=>`<option value="${x.id}">${x.name}</option>`).join('');$('#v-color-filter').value=allColors?'all':id;$('#v-width-filter').innerHTML='<option value="all">All widths</option>'+[...new Set(finishes.flatMap(x=>x.sizes))].sort((a,b)=>a-b).map(w=>`<option value="${w}">${w}″</option>`).join('');$('#v-sink-filter').value='all';$('#v-surface-filter').value='all';renderProducts();save();if(scroll)$('#v-cabinets').scrollIntoView({behavior:'smooth',block:'start'});}
function productDrawing(p){const s=styles.find(s=>s.id===p.style),w=220,h=s.id==='floating'?74:115,x=10,y=15;let fronts='';const door=(xx,ww)=>`<rect x="${xx+3}" y="${y+7}" width="${ww-6}" height="${h-14}" fill="none" stroke="#706e5e"/><path d="M${xx+ww/2-4} ${y+55}h8" stroke="#514f43" stroke-width="2"/>`;const drawers=(xx,ww)=>[0,1,2].map(i=>`<rect x="${xx+3}" y="${y+7+i*(h-14)/3}" width="${ww-6}" height="${(h-14)/3-3}" fill="none" stroke="#706e5e"/><path d="M${xx+ww/2-7} ${y+20+i*(h-14)/3}h14" stroke="#514f43" stroke-width="2"/>`).join('');if(p.sinks===2){const dw=12/p.width*w,bw=(w-dw)/2;fronts=door(x,bw)+drawers(x+bw,dw)+door(x+bw+dw,bw);}else if(p.style==='floating'){fronts=[0,1].map(i=>`<rect x="${x+4}" y="${y+5+i*(h-10)/2}" width="${w-8}" height="${(h-10)/2-3}" fill="none" stroke="#706e5e"/>`).join('');}else if(p.width<36){fronts=door(x,w/2)+door(x+w/2,w/2);}else{const dw=12/p.width*w;fronts=p.orientation.startsWith('Left')?drawers(x,dw)+door(x+dw,w-dw):door(x,w-dw)+drawers(x+w-dw,dw);}return `<svg viewBox="0 0 240 165" aria-label="${p.width}-inch cabinet front: ${esc(p.orientation)}" role="img"><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${s.color}" stroke="#5c6254"/><rect x="7" y="10" width="226" height="7" fill="#f0eee6" stroke="#7b7c6f"/>${fronts}<text x="120" y="155" text-anchor="middle" fill="#434c40" font-size="12">${p.width}″ W × ${p.depth}″ D × ${p.height}″ H</text></svg>`;}

function alternateFinishes(p){return products.filter(q=>q.id!==p.id&&styles.find(s=>s.id===q.style).family===styles.find(s=>s.id===p.style).family&&q.width===p.width&&q.depth===p.depth&&q.height===p.height&&q.sinks===p.sinks&&q.orientation===p.orientation&&JSON.stringify(q.sinkOffsets)===JSON.stringify(p.sinkOffsets));}
function renderProducts(){const s=current(),color=$('#v-color-filter').value,surface=$('#v-surface-filter').value,width=$('#v-width-filter').value,sinks=$('#v-sink-filter').value,stock=$('#v-stock-filter').checked;const list=products.filter(p=>styles.find(x=>x.id===p.style).family===s.family&&(color==='all'||p.style===color)&&(surface==='all'||styles.find(x=>x.id===p.style).material===surface)&&(width==='all'||p.width===Number(width))&&(sinks==='all'||p.sinks===Number(sinks))&&(!stock||p.stock>0));$('#v-results-count').textContent=list.length+' cabinets in '+new Set(list.map(p=>p.style)).size+' color groups';$('#v-product-list').innerHTML=list.length?list.map((p,i)=>`${i===0||list[i-1].style!==p.style?`<header class="v-color-group"><i style="background:${styles.find(x=>x.id===p.style).color}"></i><div><h3>${styles.find(x=>x.id===p.style).name}</h3><p>${styles.find(x=>x.id===p.style).surface} · ${list.filter(x=>x.style===p.style).length} matching sizes</p></div></header>`:''}<article class="v-product-card"><div class="v-product-front">${productDrawing(p)}</div><div class="v-product-detail"><span class="v-sku">${p.id}</span><h3>${p.name}</h3><p>${p.sinks===1?'Single sink':'Double sink'} · ${esc(p.orientation)}</p><dl><div><dt>Dimensions</dt><dd>${p.width} × ${p.depth} × ${p.height}″</dd></div><div><dt>Finish / material</dt><dd>${styles.find(x=>x.id===p.style).surface}<br><small>Core & door material pending</small></dd></div><div><dt>Assembly</dt><dd>${p.rta}</dd></div><div><dt>Stock example</dt><dd class="${p.stock?'v-stock-positive':'v-stock-zero'}">${p.stock?p.stock+' units · sample inventory':'0 units · availability review'}</dd></div></dl><div class="v-product-colors"><strong>Same cabinet, other colors</strong>${alternateFinishes(p).length?alternateFinishes(p).map(q=>{const c=styles.find(s=>s.id===q.style);return `<button type="button" data-v-variant="${q.id}"><i style="background:${c.color}"></i>${c.name}${q.stock?'':' · out of sample stock'}</button>`;}).join(''):'<small>This exact size and layout is shown in this color only.</small>'}</div><div class="v-cabinet-help"><button type="button" class="v-explore-button" data-v-inspect="${p.id}"><span aria-hidden="true">◇</span> Explore this cabinet in 3D <span aria-hidden="true">↗</span></button><small>Rotate, open the fronts and see the proportions.</small><button type="button" class="textlink" data-v-watch="${p.id}">Watch a manufacturer assembly demo ▶</button></div></div><div class="v-product-buy">${p.sale?'<span class="v-sale-badge">15% year-end example</span>':''}<span class="v-price">${p.sale?`<del>${money(p.price)}</del>`:''}<strong>${money(price(p))}</strong></span><small>Sample cabinet-only price</small>${p.sale?`<small>Example savings ${money(p.price-price(p))}</small>`:''}<button type="button" class="btn" data-v-add="${p.id}" ${p.stock?'':'disabled'}>${p.stock?'Add to my bathroom':'Unavailable in sample stock'}</button><a class="textlink" href="#v-assembly">Assembly help & PDF guide ↗</a></div></article>`).join(''):'<div class="v-empty"><h3>No matching cabinets</h3><p>Try another width, sink layout or stock filter.</p><button type="button" id="v-reset-filters" class="btn outline">Reset filters</button></div>';$('#v-reset-filters')?.addEventListener('click',()=>{$('#v-width-filter').value='all';$('#v-color-filter').value='all';$('#v-surface-filter').value='all';$('#v-sink-filter').value='all';$('#v-stock-filter').checked=false;renderProducts();});$$('[data-v-variant]').forEach(b=>b.onclick=()=>{const q=products.find(p=>p.id===b.dataset.vVariant);chooseStyle(q.style);$('#v-width-filter').value=String(q.width);renderProducts();});$$('[data-v-add]').forEach(b=>b.onclick=()=>add(b.dataset.vAdd));$$('[data-v-inspect]').forEach(b=>b.onclick=()=>explorer.open(b.dataset.vInspect,'model',b));$$('[data-v-watch]').forEach(b=>b.onclick=()=>explorer.open(b.dataset.vWatch,'video',b));}
function add(id){if(state.items.length>=12){feedback('Your plan can hold up to 12 units. Remove a unit before adding another.');return;}if(extras.some(x=>x.id===id)&&!state.items.some(x=>products.some(p=>p.id===x))){feedback('Select a vanity cabinet first, then add a storage companion.');$('#v-products').scrollIntoView({behavior:'smooth'});return;}const p=unit(id);if(p.stock===0)return;state.items.push(id);renderPlan();save();feedback(p.name+' added to your bathroom plan.');$('#v-room').scrollIntoView({behavior:'smooth',block:'start'});}
function measurements(){const out={};for(const [id,[min,max,fallback]]of Object.entries(fields)){const raw=$('#'+id).value;out[id]=raw!==''&&Number.isFinite(Number(raw))?Math.max(min,Math.min(max,Number(raw))):fallback;}return {width:out['v-room-width'],depth:out['v-room-depth'],offset:out['v-run-offset'],gap:out['v-run-gap'],drain:out['v-drain-x'],drainHeight:out['v-drain-height'],basinW:out['v-basin-width'],basinD:out['v-basin-depth'],exit:$('#v-plumbing-exit').value,basin:$('#v-basin-type').value};}
function arrangement(){const m=measurements();let x=m.offset;return {m,units:state.items.map(id=>{const p=unit(id),u={...p,x};x+=p.width+m.gap;return u;})};}
function renderPlan(){const {m,units}=arrangement();$('#v-plan-items').innerHTML=units.length?units.map((p,i)=>`<article class="v-plan-line"><i style="background:${p.color}"></i><div><strong>${p.name}</strong><span>${p.width} × ${p.depth} × ${p.height}″ · ${p.orientation||'Storage unit'} · ${money(price(p))}</span></div><div class="v-line-actions"><button type="button" data-v-move="${i}" data-direction="-1" aria-label="Move ${esc(p.name)} left" ${i===0?'disabled':''}>←</button><button type="button" data-v-move="${i}" data-direction="1" aria-label="Move ${esc(p.name)} right" ${i===units.length-1?'disabled':''}>→</button><button type="button" data-v-remove="${i}" aria-label="Remove ${esc(p.name)}">Remove</button></div></article>`).join(''):'<p class="v-empty-plan">Your plan is empty. Choose a style and add a cabinet from the list above to start the simulation.</p>';$('#v-plan-total').textContent=money(units.reduce((sum,p)=>sum+price(p),0));$('#v-download-plan').disabled=!units.length;$$('[data-v-remove]').forEach(b=>b.onclick=()=>{state.items.splice(Number(b.dataset.vRemove),1);renderPlan();save();feedback('Product removed from your bathroom plan.');});$$('[data-v-move]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.vMove),j=i+Number(b.dataset.direction);if(j<0||j>=state.items.length)return;[state.items[i],state.items[j]]=[state.items[j],state.items[i]];renderPlan();save();});renderDrawing(m,units);renderFit(m,units);}
function renderDrawing(m,units){let svg='';if(state.view==='plan'){const scale=Math.min(580/m.width,420/m.depth),ox=65,oy=45,w=m.width*scale,d=m.depth*scale;svg=`<svg viewBox="0 0 720 540" role="img" aria-label="Measured top-down bathroom cabinet layout"><defs><pattern id="v-floor" width="${12*scale}" height="${12*scale}" patternUnits="userSpaceOnUse"><rect width="100%" height="100%" fill="#f4f2e9"/><path d="M${12*scale} 0H0V${12*scale}" fill="none" stroke="#dfddd3" stroke-width=".7"/></pattern></defs><rect x="${ox}" y="${oy}" width="${w}" height="${d}" fill="url(#v-floor)" stroke="#7e8073" stroke-width="4"/><text x="${ox+w/2}" y="25" text-anchor="middle" font-size="15" fill="#444f41">${m.width}″ room width</text><text x="${ox+w+14}" y="${oy+d/2}" font-size="13" fill="#444f41" transform="rotate(90 ${ox+w+14} ${oy+d/2})">${m.depth}″ room depth</text>`;for(const [i,p]of units.entries()){const x=ox+p.x*scale,pw=p.width*scale,pd=p.depth*scale,overflow=p.x+p.width>m.width;svg+=`<rect x="${x}" y="${oy+pd}" width="${pw}" height="${24*scale}" fill="#d7e5de" opacity=".65" stroke="#849c8a" stroke-dasharray="4 3"/><rect x="${x}" y="${oy}" width="${pw}" height="${pd}" fill="${p.color}" stroke="${overflow?'#b14435':'#4e5946'}" stroke-width="2"/>${(p.sinkOffsets||[]).map(s=>`<ellipse cx="${x+s*scale}" cy="${oy+pd*.5}" rx="${Math.min(8*scale,pw*.2)}" ry="${4.7*scale}" fill="#fffdf7" stroke="#68705d"/>`).join('')}<text x="${x+pw/2}" y="${oy+pd+18}" text-anchor="middle" font-size="11" fill="#3c493b">${i+1} · ${p.width}″</text>`;}const dx=ox+m.drain*scale;svg+=`<line x1="${dx}" y1="${oy-8}" x2="${dx}" y2="${oy+54}" stroke="#a45f4b" stroke-width="2" stroke-dasharray="4 3"/><circle cx="${dx}" cy="${oy}" r="5" fill="#a45f4b"/><text x="${ox+w/2}" y="${oy+d*.72}" text-anchor="middle" font-size="13" fill="#7c8072">Other fixtures & door swings are not modeled</text><text x="${ox}" y="${oy+d+32}" font-size="12" fill="#5a6154">Back wall at top · units arranged left to right · room ${m.width}″ × ${m.depth}″</text></svg>`;}else{const k=Math.min(500/(m.width+m.depth*.48),300/(m.depth*.25+76)),px=(x,z)=>125+(x+z*.48)*k,py=(z,h)=>125+(z*.25-h)*k;const poly=(points,fill,stroke='#828375')=>`<polygon points="${points.map(([x,z,h])=>px(x,z)+','+py(z,h)).join(' ')}" fill="${fill}" stroke="${stroke}"/>`;svg=`<svg viewBox="0 0 720 540" role="img" aria-label="Conceptual isometric view of your selected bathroom cabinets"><g transform="translate(0 150)">${poly([[0,0,0],[m.width,0,0],[m.width,m.depth,0],[0,m.depth,0]],'#e9e6db')}${poly([[0,0,0],[m.width,0,0],[m.width,0,84],[0,0,84]],'#f3f1e8')}${poly([[0,0,0],[0,m.depth,0],[0,m.depth,84],[0,0,84]],'#e3e2d5')}`;for(const [i,p]of units.entries()){const bottom=p.style==='floating'?12:0,top=bottom+p.height,x=p.x,e=x+p.width;svg+=poly([[x,p.depth,bottom],[e,p.depth,bottom],[e,p.depth,top],[x,p.depth,top]],p.color)+poly([[e,0,bottom],[e,p.depth,bottom],[e,p.depth,top],[e,0,top]],p.color)+poly([[x,0,top],[e,0,top],[e,p.depth,top],[x,p.depth,top]],'#f7f5ee');if(p.sinks)for(const s of p.sinkOffsets){const cx=px(x+s,p.depth*.5),cy=py(p.depth*.5,top);svg+=`<ellipse cx="${cx}" cy="${cy}" rx="${7*k}" ry="${2.8*k}" fill="#fff" stroke="#7d8377"/>`;}const x1=px(x+p.width*.5,p.depth),y1=py(p.depth,top*.65);svg+=`<text x="${x1}" y="${y1}" text-anchor="middle" font-size="12" fill="${p.style==='mocha'?'white':'#3c493b'}">${i+1} · ${p.width}″</text>`;}svg+=`</g><text x="360" y="505" text-anchor="middle" font-size="13" fill="#5a6154">Concept view · verify real dimensions and mounting height</text></svg>`;}$('#v-room-drawing').innerHTML=svg;}
function fitChecks(m,units){if(!units.length)return [];const last=units.at(-1),runEnd=last.x+last.width,maxDepth=Math.max(...units.map(p=>p.depth)),approach=m.depth-maxDepth,vanities=units.filter(p=>p.sinks),drains=vanities.flatMap(p=>p.sinkOffsets.map(s=>({x:p.x+s,p}))),nearest=drains.reduce((best,d)=>!best||Math.abs(d.x-m.drain)<Math.abs(best.x-m.drain)?d:best,null),sinkWidthOK=vanities.every(p=>p.width/p.sinks>=m.basinW+4&&p.depth>=m.basinD+4);const mountConflict=vanities.some(p=>p.style==='floating')&&m.exit==='floor';return [
 {ok:runEnd<=m.width,label:runEnd<=m.width?`Cabinet run leaves ${(m.width-runEnd).toFixed(1)}″ to the right wall`:`Cabinet run exceeds the wall by ${(runEnd-m.width).toFixed(1)}″`,detail:'Includes your left offset and gaps. Fillers, overhangs and trim are not added.'},
 {ok:approach>=24,label:approach>=24?`${approach.toFixed(1)}″ of modeled space in front of the cabinets`:`Only ${approach.toFixed(1)}″ in front of the cabinet run`,detail:'24″ is a visualization allowance, not a code or accessibility approval. Other fixtures can reduce it.'},
 {ok:nearest&&Math.abs(nearest.x-m.drain)<=6,label:nearest&&Math.abs(nearest.x-m.drain)<=6?'Entered drain is within a sample sink planning zone':'Entered drain is outside the sample sink planning zones',detail:nearest?`Nearest sink center is ${nearest.x.toFixed(1)}″ from the left wall; drain is ${Math.abs(nearest.x-m.drain).toFixed(1)}″ away. Verify the actual trap and drawer envelope.`:'Add a vanity cabinet to check the entered drain.'},
 {ok:sinkWidthOK&&m.basin!=='vessel',label:m.basin==='vessel'?'Vessel basin needs a finished-height and faucet review':sinkWidthOK?'Basin cutout fits a simplified top envelope':'Basin cutout needs a wider or deeper top review',detail:'Uses 4″ total planning allowance around the cutout. Sink depth, top structure, manufacturer edge distances and undermount clips remain unverified.'},
 {ok:false,label:mountConflict?'Floor plumbing conflicts with the floating-vanity concept':'Plumbing height & structural support need review',detail:mountConflict?'Check whether the floor pipework can be rerouted before selecting a wall-mounted vanity.':`Entered drain height: ${m.drainHeight}″. No model-specific valve, drawer, P-trap or mounting specification is available yet.`}
 ];}
function renderFit(m,units){const checks=fitChecks(m,units);$('#v-fit-results').innerHTML=checks.length?'<h4>Your preliminary fit checks</h4><ul class="v-checks">'+checks.map(c=>`<li class="${c.ok?'v-check-pass':'v-check-review'}"><span aria-hidden="true">${c.ok?'✓':'!'}</span><div><strong>${c.label}</strong><small>${c.detail}</small></div></li>`).join('')+'</ul>':'<div class="v-empty-plan">Add a cabinet to see the measured layout and preliminary fit checks.</div>';}
const looks=Object.fromEntries(families.map(f=>[f.id,f.finishes[0]]));
$$('[data-v-look]').forEach(b=>b.onclick=()=>{const s=styles.find(x=>x.id===b.dataset.vLook);looks[s.family]=s.id;const img=$('[data-v-scene="'+s.family+'"]');img.src='/kabbie/assets/vanities/'+s.image;img.alt=s.name+' assembled vanity in a styled bathroom concept';$('[data-v-scene-label="'+s.family+'"]').textContent=s.name;$$('[data-v-look]').filter(x=>styles.find(s=>s.id===x.dataset.vLook).family===s.family).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
for(const f of families)$('[data-v-look="'+looks[f.id]+'"]').setAttribute('aria-pressed','true');
$$('[data-v-family]').forEach(b=>b.onclick=()=>chooseStyle(looks[b.dataset.vFamily],true));
for(const id of ['v-width-filter','v-sink-filter','v-stock-filter','v-surface-filter'])$('#'+id).onchange=renderProducts;
$('#v-color-filter').onchange=()=>{const id=$('#v-color-filter').value;if(id!=='all'){const width=$('#v-width-filter').value,sinks=$('#v-sink-filter').value,surface=$('#v-surface-filter').value;chooseStyle(id);$('#v-width-filter').value=width;$('#v-sink-filter').value=sinks;$('#v-surface-filter').value=surface;}renderProducts();};
$$('[data-v-room]').forEach(b=>b.onclick=()=>{const p=presets.find(p=>p.id===b.dataset.vRoom);$('#v-room-width').value=p.width;$('#v-room-depth').value=p.depth;$$('[data-v-room]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});renderPlan();save();});
for(const id of [...Object.keys(fields),'v-plumbing-exit','v-basin-type'])$('#'+id).addEventListener('input',()=>{$$('[data-v-room]').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-pressed','false');});renderPlan();save();});
$$('[data-v-extra]').forEach(b=>b.onclick=()=>add(b.dataset.vExtra));$$('[data-v-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.vView;$$('[data-v-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderPlan();});
$('#v-show-sale').onclick=()=>{chooseStyle('colorado-white',true);$('#v-width-filter').value='36';$('#v-stock-filter').checked=false;renderProducts();$('#v-products').scrollIntoView({behavior:'smooth'});};
$('#v-clear-plan').onclick=()=>{state.items=[];renderPlan();save();feedback('Bathroom plan cleared.');};
$('#v-download-plan').onclick=()=>{const {m,units}=arrangement();if(!units.length)return;const document={title:'Kabby Home bathroom plan - launch preview',created:new Date().toISOString(),catalogStatus:'Sample prices, inventory and product specifications. Not an order or fit approval.',room:{width:m.width,depth:m.depth,unit:'inches',leftOffset:m.offset,gap:m.gap,drainFromLeft:m.drain,drainHeight:m.drainHeight,plumbingExit:m.exit,basinType:m.basin,basinCutout:[m.basinW,m.basinD]},products:units.map(p=>({sku:p.id,name:p.name,width:p.width,depth:p.depth,height:p.height,positionFromLeft:p.x,orientation:p.orientation||'Storage unit',sampleCabinetPrice:price(p)})),sampleCabinetSubtotal:units.reduce((sum,p)=>sum+price(p),0),fitChecks:fitChecks(m,units),reviewRequired:'Actual sink templates, P-trap and valve clearance, drawers, cutouts, supports, other bathroom fixtures, code and accessibility requirements.'};const blob=new Blob([JSON.stringify(document,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=window.document.createElement('a');a.href=url;a.download='kabby-home-bathroom-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);feedback('Your bathroom plan was downloaded. Nothing has been sent.');};
chooseStyle(state.style,false,true);renderPlan();
{const m=measurements();$$('[data-v-room]').forEach(b=>{const p=presets.find(p=>p.id===b.dataset.vRoom),match=p.width===m.width&&p.depth===m.depth;b.classList.toggle('selected',match);b.setAttribute('aria-pressed',String(match));});}
for(const [id,[min,max,fallback]]of Object.entries(fields))$('#'+id).addEventListener('change',()=>{const input=$('#'+id),n=Number(input.value);if(input.value===''||!Number.isFinite(n)||n<min||n>max){input.value=Number.isFinite(n)&&input.value!==''?Math.max(min,Math.min(max,n)):fallback;feedback('Measurement adjusted to the supported '+min+'–'+max+' inch range.');renderPlan();save();}});

$('#v-main-reference-play').onclick=()=>{$('#v-main-reference-player').innerHTML='<iframe title="RTA Cabinet Store V30 vanity assembly demonstration" src="https://www.youtube-nocookie.com/embed/q20fu7xHLCA?autoplay=1&rel=0" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>';};

$('[data-v-tower]').onclick=()=>{chooseStyle('natural-shaker',true);$('#v-width-filter').value='36';renderProducts();$('#v-selected-title').textContent='Vanity + Linen Tower';$('#v-selected-image').src='/kabbie/assets/vanities/vanity-natural-linen-tower.png';$('#v-selected-image').alt='Natural Shaker sink cabinet beside matching tall linen tower bathroom concept';$('#v-selected-description').innerHTML='<span class="eyebrow">Craftsman Natural Shaker · coordinated storage</span><h3>36″ vanity + 18″ linen tower</h3><p>54″ combined cabinet width before gaps and fillers. The sample tower is 18″ W × 18″ D × 72″ H.</p><p>Add the sink cabinet below, then use “18″ linen tower” under storage companions in your bathroom plan.</p><small>Concept render. Matching finishes, construction and final availability require supplier confirmation. Cabinet and tower are separate selections.</small>';};

